starterCode:
totals = {}
while True:
    line = input().strip()
    if not line:
        break
    amount, category = line.split()
    totals[category] = totals.get(category, 0) + float(amount)
if not totals:
    print("Пусто")
else:
    all_sum = sum(totals.values())
    for category, amount in sorted(totals.items(), key=lambda p: (p[1], p[0])):
        print(f"{category}: {round(amount, 2)} ({round(amount // all_sum * 100, 1)}%)")

